_{\substack{\epsilon\ =\ 0^{+}\\[1mm] \mu\ =\ 0\,\,}}
\\[5mm] = & \
\left.-\,\partiald{H_{\mu}}{\mu}
\right\vert_{\mu\ =\ 0} = \bbx{\color{#44f}{-\,{\pi^{2} \over 6}}}
\approx -1.6449 \\ &
\end{align} 
