   return output; // Deitel and Deitel page 445
}



int IntSqrt(int i)
{
  // cerr << "called intsqrt  with   " << i << endl;
  if ( i <= 0 ) return 0;
  else if ( i <= 3) return 1;
  else if ( i >= 2147395600) return 46340;
  else
  {
    float r;
    r = 1.0 * i;
    r = sqrt(r);
    int root = (int) ceil(r);
    while ( root * root   <= i ) ++root;
    while ( root * root   > i ) --root;
    return  root ;
  }
}


int SquareQ(int i)
{
  if ( i < 0 ) return 0;
  else if ( i <= 1) return 1;
  else
  {
    int root = IntSqrt(i);
    return i == root * root ;
  }
}






